    else if (!(Option(e.tenantId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "ConceptRemoved.tenantId 必须存在"))
    // @knowledge 1bfaf869-caee-4e41-a373-9dfa99ab7f07@1e30ee3de8dad0a1
    // ir_evt_ConceptRemoved_timestamp
    else if (!(Option(e.timestamp).isDefined)) Some(iMadzError("EVENT_NO_TIMESTAMP", "ConceptRemoved.timestamp 不能为空"))
    else None

  private def firstBadConceptsMerged(e: ConceptsMerged): Option[iMadzError] =
    // @knowledge a9ba7bdc-34d0-46c3-852f-9c3f51c4b697@08a3bad4114c7be9
    // IR-CON-EVT-010_sourceConceptId
    if (!(Option(e.sourceConceptId).isDefined)) Some(iMadzError("CON_MERGE_INCOMPLETE", "ConceptsMerged.sourceConceptId 必须非空"))
    // @knowledge a9ba7bdc-34d0-46c3-852f-9c3f51c4b697@08a3bad4114c7be9
    // IR-CON-EVT-010_targetConceptId
    else if (!(Option(e.targetConceptId).isDefined)) Some(iMadzError("CON_MERGE_INCOMPLETE", "ConceptsMerged.targetConceptId 必须非空"))
    // @knowledge a9ba7bdc-34d0-46c3-852f-9c3f51c4b697@08a3bad4114c7be9
    // ir_evt_ConceptsMerged_sourceConceptId_not_null
    else if (!(Option(e.sourceConceptId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "ConceptsMerged.sourceConceptId 必须存在"))
    // @knowledge a9ba7bdc-34d0-46c3-852f-9c3f51c4b697@08a3bad4114c7be9
    // ir_evt_ConceptsMerged_targetConceptId_not_null
    else if (!(Option(e.targetConceptId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "ConceptsMerged.targetConceptId 必须存在"))
    // @knowledge a9ba7bdc-34d0-46c3-852f-9c3f51c4b697@08a3bad4114c7be9
    // ir_evt_ConceptsMerged_tenantId_not_null
    else if (!(Option(e.tenantId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "ConceptsMerged.tenantId 必须存在"))
    // @knowledge a9ba7bdc-34d0-46c3-852f-9c3f51c4b697@08a3bad4114c7be9
    // ir_evt_ConceptsMerged_timestamp
    else if (!(Option(e.timestamp).isDefined)) Some(iMadzError("EVENT_NO_TIMESTAMP", "ConceptsMerged.timestamp 不能为空"))
    else None

  private def firstBadConceptLandingsRecorded(e: ConceptLandingsRecorded): Option[iMadzError] =
    // @knowledge 620fe57e-0521-44fd-8ceb-e799dccd463d@c246b249217d2965
    // ir_evt_ConceptLandingsRecorded_conceptId_not_null
    if (!(Option(e.conceptId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "ConceptLandingsRecorded.conceptId 必须存在"))
    // @knowledge 620fe57e-0521-44fd-8ceb-e799dccd463d@c246b249217d2965
    // ir_evt_ConceptLandingsRecorded_tenantId_not_null
    else if (!(Option(e.tenantId).isDefined)) Some(iMadzError("EVENT_BAD_ID", "ConceptLandingsRecorded.tenantId 必须存在"))
    // @knowledge 620fe57e-0521-44fd-8ceb-e799dccd463d@c246b249217d2965
    // ir_evt_ConceptLandingsRecorded_timestamp
    else if (!(Option(e.timestamp).isDefined)) Some(iMadzError("EVENT_NO_TIMESTAMP", "ConceptLandingsRecorded.timestamp 不能为空"))
    else None

}
